<script setup lang="ts">import type {Point} from '../types/domain';import {fixed} from '../utils/format';import {rangeLabels} from '../constants/enums';withDefaults(defineProps<{rows:Point[];showReason?:boolean}>(),{showReason:false})</script><template><div class="table-wrap"><table><thead><tr><th v-if="showReason">样本</th><th>配对编号</th><th>量程</th><th>X</th><th>Y</th><th>差值 y−x</th><th>界限外</th><th v-if="showReason">剔除原因</th></tr></thead><tbody><tr v-for="p in rows" :key="p.pair_id" :class="{'excluded-row':showReason&&p.included===false}"><td v-if="showReason">{{p.included===false?'剔除':'保留'}}</td><td>{{p.pair_id}}</td><td>{{rangeLabels[p.range_label]}}</td><td>{{fixed(p.x)}}</td><td>{{fixed(p.y)}}</td><td>{{fixed(p.difference??p.y-p.x)}}</td><td>{{p.outside_loa?'待复核':'—'}}</td><td v-if="showReason">{{p.included===false?(p.exclusion_reason||'—'):'—'}}</td></tr></tbody></table></div></template>
